# Multiply all numbers in a list:
def multiply_list(mylist):
    result = 1
    for x in mylist:
        result = result * int(x)
    return result


# Ask for a number
big_number = input("Give me a big number: ")
product_size = int(input("How many numbers should be in the product?: "))
products = []

n = 0
# while loop should run until we get to the last four digits of the big number.
# The last digit is indexed by len(big_number)-1. We want n+3=len(big_number)-1 on the last case.
# So we run until n+3=len(big_number)
while True:
    # Check the product of four numbers starting from the first four.
    products.append(multiply_list([big_number[i] for i in range(n, n + product_size)]))
    print([big_number[i] for i in range(n, n + product_size)])
    if n + product_size == len(str(big_number)):
        break
    n += 1

print(products)
print(max(products))

